#[test]
fn test_pp_word_calibration_is_monotone_at_every_permille() {
    let mut i: i32 = 0;
    let mut previous: i32 = 0;
    while i < 1001 {
        let p: i32 = ocal_word(2, 0, i);
        crate::testport::assert_that(p >= previous, "weighted isotonic calibration");
        previous = p;
        i += 1;
    }
}
#[test]
fn test_pp_calibration_floors_millionths_at_bin_edges() {
    let mut edge: i32 = 100000;
    while edge < 1000000 {
        crate::testport::assert_eq(ocal_word(2, 0, (edge - 1) / 1000), ocal_word(2, 0, (edge / 1000) - 1), "below edge");
        crate::testport::assert_eq(ocal_word(2, 0, (edge + 1) / 1000), ocal_word(2, 0, edge / 1000), "above edge");
        edge += 100000;
    }
}
#[test]
fn test_pp_inverted_bins_pool_the_original_fit_observations() {
    crate::testport::assert_eq(ocal_word(2, 0, 600), 422, "57 correct of 135");
    crate::testport::assert_eq(ocal_word(2, 0, 799), 422, "same pooled bin");
    crate::testport::assert_eq(ocal_word(2, 0, 800), 521, "next frozen bin");
    crate::testport::assert_eq(ocal_word(3, 0, 1000), -1, "unfitted engine is not a zero probability");
}
